+    // Expose React internals
+    window.__REACT_DEVTOOLS_GLOBAL_HOOK__ = {
+        ...window.__REACT_DEVTOOLS_GLOBAL_HOOK__,
+        onCommitFiberRoot: (id, root) => {
+            // Custom commit logging
+            console.debug('React commit:', root);
+        }
+    };
+}
+```
