+// error-tracker.ts
+interface ErrorEvent {
+    timestamp: Date;
+    level: 'debug' | 'info' | 'warning' | 'error' | 'fatal';
+    message: string;
+    stack?: string;
+    context: {
+        user?: any;
+        request?: any;
+        environment: string;
+        release: string;
+        tags: Record<string, string>;
+        extra: Record<string, any>;
+    };
+    fingerprint: string[];
+}
